closeb=tk.Button(root,text="Close app",bg="grey17",fg="white",font=("Calibri",24),activeforeground="white",activebackground="grey21",command=close)
closeb.grid(row=11,column=0,columnspan=3,sticky="NESW")
root.mainloop()
